import "./lib/error-capture";

import handler, { createServerEntry } from "@tanstack/react-start/server-entry";
import { consumeLastCapturedError } from "./lib/error-capture";
import { renderErrorPage } from "./lib/error-page";
import { logServerError } from "./server/logging";

/**
 * Convert the generic JSON 500 generated by the Start/H3 layer into the
 * application's HTML error page while preserving the original error in logs.
 */
async function normalizeCatastrophicSsrResponse(response: Response): Promise<Response> {
  if (response.status < 500) return response;

  const contentType = response.headers.get("content-type") ?? "";
  if (!contentType.includes("application/json")) return response;

  const body = await response.clone().text();
  if (!isUnhandledServerError(body)) return response;

  logServerError(
    "[request] unhandled SSR response",
    consumeLastCapturedError() ?? new Error(`Unhandled SSR error: ${body}`),
  );
  return new Response(renderErrorPage(), {
    status: 500,
    headers: { "content-type": "text/html; charset=utf-8" },
  });
}

function isUnhandledServerError(body: string): boolean {
  try {
    const payload = JSON.parse(body) as {
      error?: unknown;
      status?: unknown;
      statusCode?: unknown;
      unhandled?: unknown;
      message?: unknown;
    };

    // TanStack/Nitro/H3 versions have emitted both
    // { status: 500, unhandled: true, message: "HTTPError" }
    // and { error: true, status: 500, unhandled: true }.
    return (
      payload.unhandled === true &&
      (payload.status === 500 || payload.statusCode === 500 || payload.message === "HTTPError")
    );
  } catch {
    return false;
  }
}

export default createServerEntry({
  async fetch(request, options) {
    const requestId = request.headers.get("x-nf-request-id") || crypto.randomUUID();

    try {
      const response = await handler.fetch(request, options);
      const normalized = await normalizeCatastrophicSsrResponse(response);
      const headers = new Headers(normalized.headers);
      headers.set("x-request-id", requestId);

      return new Response(normalized.body, {
        status: normalized.status,
        statusText: normalized.statusText,
        headers,
      });
    } catch (error) {
      logServerError("[request] unhandled failure", error, {
        requestId,
        method: request.method,
        path: new URL(request.url).pathname,
      });

      return new Response(renderErrorPage(), {
        status: 500,
        headers: {
          "content-type": "text/html; charset=utf-8",
          "x-request-id": requestId,
        },
      });
    }
  },
});
